const libphonenumber=window.libphonenumber||{},examples=window.libphonenumberExamples||{};class InternationalPhoneField{constructor(t){this.wrapperElement=t;let e={};try{e=JSON.parse(this.wrapperElement.dataset.options||"{}")}catch{console.warn("International Phone Field: Invalid options JSON, using defaults")}if(this.options=e,this.countrySelectElement=this.wrapperElement.querySelector(".dce-international-phone-country"),this.phoneInputElement=this.wrapperElement.querySelector(".dce-international-phone-number"),this.hiddenField=this.wrapperElement.querySelector(".dce-international-phone-value"),!this.countrySelectElement||!this.phoneInputElement||!this.hiddenField){console.warn("International Phone Field: Missing required elements");return}}init(){this.updatePlaceholder(),this.setupEventListeners(),this.hiddenField.value&&this.parseInitialValue(this.hiddenField.value)}setupEventListeners(){this.countrySelectElement.addEventListener("change",()=>{this.updatePlaceholder(),this.updateValue()}),this.phoneInputElement.addEventListener("input",e=>{try{const r=this.createAsYouTypeFormatter(this.countrySelectElement.value).input(e.target.value);(r.length>=e.target.value.length||e.inputType==="deleteContentBackward")&&(e.target.value=r)}catch{}this.updateValue()});const t=this.wrapperElement.closest("form");t&&t.addEventListener("reset",()=>{setTimeout(()=>{this.hiddenField.value="",this.updatePlaceholder()},0)})}createAsYouTypeFormatter(t){return libphonenumber.AsYouType?new libphonenumber.AsYouType(t):{input:e=>e}}updatePlaceholder(){if(!this.options.showExample)return;const t=this.countrySelectElement.value;try{if(libphonenumber.getExampleNumber){const e=libphonenumber.getExampleNumber(t,examples);if(e){this.phoneInputElement.placeholder=e.formatNational();return}}}catch{}}updateValue(){const t=this.countrySelectElement.value,e=this.phoneInputElement.value.trim();if(e){try{if(libphonenumber.parsePhoneNumberFromString){const o=libphonenumber.parsePhoneNumberFromString(e,t);if(o)this.hiddenField.value=o.format("E.164");else{const l=this.countrySelectElement.selectedOptions[0]?.dataset?.prefix||"";this.hiddenField.value=l?`+${l}${e.replace(/\D/g,"")}`:e}this.options.validation&&this.validatePhoneNumber();return}}catch{}const r=this.countrySelectElement.selectedOptions[0]?.dataset?.prefix||"";this.hiddenField.value=r?`+${r}${e.replace(/\D/g,"")}`:e}else this.hiddenField.value=""}parseInitialValue(t){try{if(libphonenumber.parsePhoneNumberFromString){const e=libphonenumber.parsePhoneNumberFromString(t);if(e){e.country&&(this.countrySelectElement.value=e.country,this.updatePlaceholder()),this.phoneInputElement.value=e.formatNational();return}}}catch{}t.startsWith("+")?this.phoneInputElement.value=t.substring(1):this.phoneInputElement.value=t}validatePhoneNumber(){const t=this.countrySelectElement.value,e=this.phoneInputElement.value.trim();if(!e){this.phoneInputElement.setCustomValidity("");return}try{if(libphonenumber.parsePhoneNumberFromString){const i=libphonenumber.parsePhoneNumberFromString(e,t);i?i.isValid()?this.phoneInputElement.setCustomValidity(""):this.phoneInputElement.setCustomValidity("This phone number appears to be invalid"):this.phoneInputElement.setCustomValidity("Invalid phone number format");return}}catch{}this.phoneInputElement.setCustomValidity("")}}function initializeWrapper(n){if(n.dataset.dcePhoneInitialized)return;const t=new InternationalPhoneField(n);t.countrySelectElement&&(t.init(),n.dataset.dcePhoneInitialized="true")}function initializeInternationalPhoneFields(n){(n?n[0]:document).querySelectorAll(".dce-international-phone-wrapper").forEach(initializeWrapper)}jQuery(window).on("elementor/frontend/init",function(){elementorFrontend.hooks.addAction("frontend/element_ready/form.default",initializeInternationalPhoneFields)});
